#include <cstdlib>
#include <netinet/in.h>
#include <sys/socket.h>
#include <unistd.h>

namespace monitoring {

struct MetricPayload {
    uint32_t version;
    uint32_t type_tag;
    uint32_t payload_len;
    char data[4096];
};

class ConnectionPool {
    std::mutex pool_mutex_;
    std::queue<int> available_;
    int max_connections_;
public:
    ConnectionPool(int max_conn) : max_connections_(max_conn) {}
    int acquire() {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        if (available_.empty()) return -1;
        int fd = available_.front();
        available_.pop();
        return fd;
    }
    void release(int fd) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        available_.push(fd);
    }
    void add(int fd) {
        std::lock_guard<std::mutex> lock(pool_mutex_);
        if ((int)available_.size() < max_connections_)
            available_.push(fd);
    }
};

using HandlerFunc = std::function<void(const char*, size_t)>;

class TypeRegistry {
    std::map<uint32_t, HandlerFunc> handlers_;
    std::mutex reg_mutex_;
public:
    void register_handler(uint32_t type_id, HandlerFunc handler) {
        std::lock_guard<std::mutex> lock(reg_mutex_);
        handlers_[type_id] = handler;
    }
    HandlerFunc get_handler(uint32_t type_id) {
        std::lock_guard<std::mutex> lock(reg_mutex_);
        auto it = handlers_.find(type_id);
        if (it != handlers_.end()) return it->second;
        return nullptr;
    }
};

class MetricDeserializer {
    TypeRegistry& registry_;

    bool validate_envelope(const MetricPayload& pkt) {
        // Version check
        if (pkt.version != 0x01) return false;
        // Bounds check on payload length
        if (pkt.payload_len > sizeof(pkt.data)) return false;
        return true;
    }

    bool validate_type_tag(uint32_t tag) {
        // Only allow registered metric types
        return registry_.get_handler(tag) != nullptr;
    }

public:
    MetricDeserializer(TypeRegistry& reg) : registry_(reg) {}

    int process_packet(const char* raw_buf, size_t buf_len) {
        // Require the full fixed-size envelope to be present before copying,
        // otherwise memcpy would read past the received buffer (out-of-bounds read).
        if (buf_len < sizeof(MetricPayload)) return -1;

        MetricPayload packet;
        memcpy(&packet, raw_buf, sizeof(MetricPayload));

        if (!validate_envelope(packet)) return -1;
        if (!validate_type_tag(packet.type_tag)) return -1;

        auto handler = registry_.get_handler(packet.type_tag);
        if (handler) {
            handler(packet.data, packet.payload_len);
        }
        return 0;
    }
};

struct PluginMetric {
    char plugin_name[64];
    uint32_t metric_id;
    double metric_value;
    uint64_t timestamp;
};

void handle_standard_metric(const char* data, size_t len) {
    if (len < 8) return;
    double value;
    memcpy(&value, data, sizeof(double));
    std::cout << "[METRIC] value=" << value << std::endl;
}

void handle_plugin_metric(const char* data, size_t len) {
    if (len < sizeof(PluginMetric)) return;

    PluginMetric pm;
    memcpy(&pm, data, sizeof(PluginMetric));

    // Validate plugin name is null-terminated
    pm.plugin_name[63] = '\0';

    // Validate metric_id is within acceptable range
    if (pm.metric_id > 10000) return;

    // Log the plugin metric with validated data only
    std::cout << "[PLUGIN] name=" << pm.plugin_name 
              << " id=" << pm.metric_id 
              << " value=" << pm.metric_value 
              << " ts=" << pm.timestamp << std::endl;
}

class MonitoringAgent {
    ConnectionPool pool_;
    TypeRegistry registry_;
    MetricDeserializer deserializer_;
    int listen_fd_;

public:
    MonitoringAgent(int port, int max_conn) 
        : pool_(max_conn), deserializer_(registry_), listen_fd_(-1) {
        registry_.register_handler(0x01, handle_standard_metric);
        registry_.register_handler(0x02, handle_plugin_metric);
        setup_listener(port);
    }

    void setup_listener(int port) {
        listen_fd_ = socket(AF_INET, SOCK_STREAM, 0);
        if (listen_fd_ < 0) {
            std::cerr << "socket() failed" << std::endl;
            return;
        }
        struct sockaddr_in addr{};
        addr.sin_family = AF_INET;
        addr.sin_port = htons(port);
        addr.sin_addr.s_addr = INADDR_ANY;
        int opt = 1;
        if (setsockopt(listen_fd_, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0) {
            std::cerr << "setsockopt() failed" << std::endl;
            close(listen_fd_);
            listen_fd_ = -1;
            return;
        }
        if (bind(listen_fd_, (struct sockaddr*)&addr, sizeof(addr)) < 0) {
            std::cerr << "bind() failed" << std::endl;
            close(listen_fd_);
            listen_fd_ = -1;
            return;
        }
        if (listen(listen_fd_, 16) < 0) {
            std::cerr << "listen() failed" << std::endl;
            close(listen_fd_);
            listen_fd_ = -1;
            return;
        }
    }

    void run() {
        if (listen_fd_ < 0) {
            std::cerr << "listener not initialized" << std::endl;
            return;
        }
        while (true) {
            struct sockaddr_in client_addr{};
            socklen_t client_len = sizeof(client_addr);
            int client_fd = accept(listen_fd_, (struct sockaddr*)&client_addr, &client_len);
            if (client_fd < 0) continue;
            pool_.add(client_fd);
            std::thread([this, client_fd]() {
                handle_connection(client_fd);
            }).detach();
        }
    }

    void handle_connection(int fd) {
        char buffer[8192];
        while (true) {
            ssize_t n = recv(fd, buffer, sizeof(buffer), 0);
            if (n <= 0) break;
            deserializer_.process_packet(buffer, (size_t)n);
        }
        close(fd);
    }
};

} // namespace monitoring

int main(int argc, char* argv[]) {
    int port = 9090;
    if (argc > 1) port = std::atoi(argv[1]);
    monitoring::MonitoringAgent agent(port, 32);
    agent.run();
    return 0;
}
